import csv,math,collections,numpy as np
from scipy.optimize import minimize
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/80aefb383357367b/repo/_runs/cell_1/experiment2/model_loop/responses.csv')))
PR={n for n in range(2,101) if all(n%d for d in range(2,int(n**.5)+1))}
def props(n):
    p={"even" if n%2==0 else "odd", f"last{n%10}", f"dec{min(n//10,9)}"}
    p|={f"has{d}" for d in set(str(n))}
    if n in PR:p.add("prime")
    if round(n**.5)**2==n:p.add("sq")
    if round(n**(1/3))**3==n:p.add("cube")
    for k in range(2,11):
        if n in {k**e for e in range(1,8)}:p.add(f"pow{k}")
    for k in range(3,13):
        if n%k==0:p.add(f"mult{k}")
    return p
P={n:props(n) for n in range(1,101)}
C=collections.Counter(q for n in P for q in P[n]); R={q:-math.log(C[q]/100) for q in C}
y=np.array([int(r['rating']) for r in rows])
feats=collections.defaultdict(list)
for r in rows:
    ex=[int(x) for x in r['number_set'].split(',')];t=int(r['target'])
    sh=set.intersection(*(P[x] for x in ex))
    tot=sum(R[q] for q in sh); hit=sum(R[q] for q in sh if q in P[t])
    feats['A'].append(hit/tot if tot else 0)
    feats['B'].append(max([R[q] for q in sh if q in P[t]],default=0))
    feats['Bm'].append(max([R[q] for q in sh if q not in P[t]],default=0))
    # per-example shared-distinctiveness similarity
    feats['C'].append(np.mean([sum(R[q] for q in P[x]&P[t])/sum(R[q] for q in P[x]) for x in ex]))
    lo,hi=min(ex),max(ex); feats['hull'].append(max(0,lo-t,t-hi)/100)
    feats['n'].append(len(ex))
def fit(cols):
    X=np.column_stack([np.ones(len(y))]+[np.array(feats[c]) for c in cols])
    f=lambda w: -np.sum(y*(X@w)-np.logaddexp(0,X@w))
    return minimize(f,np.zeros(X.shape[1])).fun
for cols in [[],['A'],['B'],['Bm'],['C'],['hull'],['A','hull'],['Bm','hull']]: print(cols,round(fit(cols),1))
